<template>
  <div class="gar-root">
    <!-- Loading Overlay -->
    <v-overlay :value="loading" z-index="999">
      <div class="gar-loader">
        <div class="gar-loader__dots">
          <span></span><span></span><span></span>
        </div>
        <div class="gar-loader__text">Loading adjustment…</div>
      </div>
    </v-overlay>

    <!-- Hero Header -->
    <header class="gar-hero">
      <div class="gar-hero__pattern"></div>
      <div class="gar-hero__inner">
        <div class="gar-hero__breadcrumb">
          <span class="gar-hero__back" @click="$router.go(-1)">
            <v-icon size="13" color="rgba(255,255,255,0.6)"
              >mdi-arrow-left</v-icon
            >
            Back
          </span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <v-icon size="14" color="#f97316">mdi-home</v-icon>
          <span>Ministry of Health</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span>Performance Management</span>
          <v-icon size="12" color="#fdba74">mdi-chevron-right</v-icon>
          <span class="gar-hero__breadcrumb-active">Adjustment Review</span>
          <v-spacer></v-spacer>
          <span class="gar-hero__role-tag">
            <v-icon size="12" color="#fdba74">mdi-shield-check</v-icon>
            {{ currentReviewerLabel }}
          </span>
        </div>

        <div class="gar-hero__content">
          <div class="gar-hero__left">
            <div class="gar-hero__badge">
              <v-icon size="14" color="#f97316">mdi-auto-fix</v-icon>
              Goal Adjustment Review
            </div>
            <div class="gar-hero__title-row">
              <h1 class="gar-hero__title">
                {{ performancePlan ? performancePlan.name : "Loading…" }}
              </h1>
            </div>
            <div class="gar-hero__meta">
              <div v-if="staffName" class="gar-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-account</v-icon>
                <span>{{ staffName }}</span>
              </div>
              <div v-if="staffName" class="gar-hero__meta-sep"></div>
              <div class="gar-hero__meta-item">
                <v-icon size="15" color="#fdba74">mdi-calendar</v-icon>
                <span>FY {{ selectedFiscalYear }}</span>
              </div>
              <div v-if="performancePlan" class="gar-hero__meta-sep"></div>
              <div
                v-if="performancePlan"
                class="gar-hero__status"
                :class="`gar-hero__status--${adjustmentStatus}`"
              >
                {{ adjustmentStatusLabel }}
              </div>
            </div>
          </div>

          <div class="gar-hero__right" v-if="performancePlan">
            <div class="gar-hero__stats">
              <div class="gar-hero__stat">
                <div class="gar-hero__stat-num gar-hero__stat-num--red">
                  {{ dropsCount }}
                </div>
                <div class="gar-hero__stat-label">Drops</div>
              </div>
              <div class="gar-hero__stat-div"></div>
              <div class="gar-hero__stat">
                <div class="gar-hero__stat-num gar-hero__stat-num--amber">
                  {{ modifiesCount }}
                </div>
                <div class="gar-hero__stat-label">Replaces</div>
              </div>
              <div class="gar-hero__stat-div"></div>
              <div class="gar-hero__stat">
                <div class="gar-hero__stat-num gar-hero__stat-num--green">
                  {{ addsCount }}
                </div>
                <div class="gar-hero__stat-label">Adds</div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </header>

    <!-- Body -->
    <div class="gar-body">
      <!-- Gate: still verifying access -->
      <div v-if="!accessChecked" class="gar-empty">
        <v-progress-circular indeterminate color="#6366f1" size="40" />
        <p class="mt-3 gar-empty__desc">Verifying access…</p>
      </div>

      <!-- Gate: not a supervisor or HOD -->
      <div v-else-if="!isSupervisor && !isHOD" class="gar-empty">
        <div class="gar-empty__icon-wrap">
          <v-icon size="48" color="#dc2626">mdi-lock-outline</v-icon>
        </div>
        <h2 class="gar-empty__title">Access Restricted</h2>
        <p class="gar-empty__desc">
          This page is only accessible to the staff member’s direct supervisor
          or their Head of Department.
        </p>
      </div>

      <!-- Gate: HOD but staff outside their facility coverage -->
      <div
        v-else-if="isHOD && !isSupervisor && !staffInCoverage"
        class="gar-empty"
      >
        <div class="gar-empty__icon-wrap">
          <v-icon size="48" color="#dc2626">mdi-lock-outline</v-icon>
        </div>
        <h2 class="gar-empty__title">Access Restricted</h2>
        <p class="gar-empty__desc">
          This staff member's facility is outside your HOD coverage area.
        </p>
      </div>

      <!-- Gate: HOD blocked until supervisor approves -->
      <div
        v-else-if="isHOD && !isSupervisor && !hodCanAccess"
        class="gar-empty"
      >
        <div class="gar-empty__icon-wrap">
          <v-icon size="48" color="#f97316">mdi-clock-lock-outline</v-icon>
        </div>
        <h2 class="gar-empty__title">Pending Supervisor Approval</h2>
        <p class="gar-empty__desc">
          This adjustment is not yet available for HOD review. It will become
          accessible once the supervisor has approved it.
        </p>
      </div>

      <!-- No plan / no adjustment -->
      <div v-else-if="!loading && !performancePlan" class="gar-empty">
        <div class="gar-empty__icon-wrap">
          <v-icon size="48" color="#64748b">mdi-file-search-outline</v-icon>
        </div>
        <h2 class="gar-empty__title">No plan found</h2>
        <p class="gar-empty__desc">
          No performance plan was found for this staff member in
          <strong>FY {{ selectedFiscalYear }}</strong
          >.
        </p>
      </div>

      <div v-else-if="!loading && adjustments.length === 0" class="gar-empty">
        <div class="gar-empty__icon-wrap">
          <v-icon size="48" color="#64748b">mdi-inbox-arrow-down</v-icon>
        </div>
        <h2 class="gar-empty__title">No adjustment to review</h2>
        <p class="gar-empty__desc">
          This staff member has not submitted a mid-year goal adjustment.
        </p>
      </div>

      <template v-else-if="performancePlan">
        <!-- Status banners (for HOD reviewing after supervisor) -->
        <v-alert
          v-if="statusBanner"
          :type="statusBanner.type"
          outlined
          dense
          class="gar-status-alert"
        >
          <v-icon small left>{{ statusBanner.icon }}</v-icon>
          <strong>{{ statusBanner.title }}</strong>
          {{ statusBanner.text }}
        </v-alert>

        <v-row>
          <!-- Adjustment list -->
          <v-col :cols="canReview ? 7 : 12">
            <div class="gar-section">
              <div class="gar-section__head">
                <v-icon size="16" color="#6366f1">mdi-playlist-edit</v-icon>
                <span class="gar-section__title"
                  >Proposed changes · {{ adjustments.length }}</span
                >
              </div>

              <div class="gar-adj-list">
                <div
                  v-for="adj in adjustments"
                  :key="adj.id"
                  class="gar-adj"
                  :class="`gar-adj--${adj.adjustmentType}`"
                >
                  <div class="gar-adj__head">
                    <div
                      class="gar-adj__chip"
                      :class="`gar-adj__chip--${adj.adjustmentType}`"
                    >
                      <v-icon
                        size="11"
                        :color="chipColor(adj.adjustmentType)"
                        >{{ chipIcon(adj.adjustmentType) }}</v-icon
                      >
                      {{ chipLabel(adj.adjustmentType) }}
                    </div>
                    <div class="gar-adj__type">
                      {{ goalTypeLabel(adjGoalType(adj)) }}
                    </div>
                    <v-spacer></v-spacer>
                    <div class="gar-adj__date">
                      <v-icon size="11" color="#94a3b8"
                        >mdi-clock-outline</v-icon
                      >
                      {{ formatDate(adj.eventDate) }}
                    </div>
                  </div>

                  <!-- Body: varies by type -->
                  <!-- DROP: show only old goal -->
                  <div
                    v-if="adj.adjustmentType === 'drop'"
                    class="gar-adj__body"
                  >
                    <div class="gar-goal-card gar-goal-card--drop">
                      <div class="gar-goal-card__label">
                        <v-icon size="11" color="#dc2626"
                          >mdi-delete-outline</v-icon
                        >
                        Dropping this goal
                      </div>
                      <div class="gar-goal-card__name">
                        {{ goalName(adj.oldGoalId) }}
                      </div>
                      <div
                        class="gar-goal-card__desc"
                        v-if="goalDesc(adj.oldGoalId)"
                      >
                        {{ goalDesc(adj.oldGoalId) }}
                      </div>
                      <div class="gar-goal-card__path">
                        <v-icon size="10" color="#94a3b8"
                          >mdi-sitemap-outline</v-icon
                        >
                        {{ goalPath(adj.oldGoalId) }}
                      </div>
                    </div>
                  </div>

                  <!-- REPLACE: show old on left, new on right -->
                  <div
                    v-else-if="
                      ['replace', 'modify'].includes(adj.adjustmentType)
                    "
                    class="gar-adj__body"
                  >
                    <div class="gar-diff">
                      <div class="gar-goal-card gar-goal-card--old">
                        <div class="gar-goal-card__label">
                          <v-icon size="11" color="#64748b"
                            >mdi-archive-outline</v-icon
                          >
                          Current
                        </div>
                        <div class="gar-goal-card__name">
                          {{ goalName(adj.oldGoalId) }}
                        </div>
                        <div
                          class="gar-goal-card__desc"
                          v-if="goalDesc(adj.oldGoalId)"
                        >
                          {{ goalDesc(adj.oldGoalId) }}
                        </div>
                        <div class="gar-goal-card__path">
                          <v-icon size="10" color="#94a3b8"
                            >mdi-sitemap-outline</v-icon
                          >
                          {{ goalPath(adj.oldGoalId) }}
                        </div>
                      </div>
                      <div class="gar-diff__arrow">
                        <v-icon size="22" color="#d97706"
                          >mdi-arrow-right-thick</v-icon
                        >
                      </div>
                      <div class="gar-goal-card gar-goal-card--new">
                        <div class="gar-goal-card__label">
                          <v-icon size="11" color="#059669"
                            >mdi-sparkles</v-icon
                          >
                          Proposed
                        </div>
                        <div class="gar-goal-card__name">
                          {{ goalName(adj.supersededById) }}
                        </div>
                        <div
                          class="gar-goal-card__desc"
                          v-if="goalDesc(adj.supersededById)"
                        >
                          {{ goalDesc(adj.supersededById) }}
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- ADD: show only new goal -->
                  <div v-else class="gar-adj__body">
                    <div class="gar-goal-card gar-goal-card--add">
                      <div class="gar-goal-card__label">
                        <v-icon size="11" color="#059669"
                          >mdi-plus-circle-outline</v-icon
                        >
                        Adding new goal
                      </div>
                      <div class="gar-goal-card__name">
                        {{ goalName(adj.supersededById) }}
                      </div>
                      <div
                        class="gar-goal-card__desc"
                        v-if="goalDesc(adj.supersededById)"
                      >
                        {{ goalDesc(adj.supersededById) }}
                      </div>
                      <div
                        class="gar-goal-card__path"
                        v-if="goalParentName(adj.supersededById)"
                      >
                        <v-icon size="10" color="#94a3b8"
                          >mdi-sitemap-outline</v-icon
                        >
                        Under: {{ goalParentName(adj.supersededById) }}
                      </div>
                    </div>
                  </div>

                  <!-- Reason -->
                  <div class="gar-adj__reason">
                    <div class="gar-adj__reason-label">
                      <v-icon size="11" color="#64748b"
                        >mdi-message-text-outline</v-icon
                      >
                      Staff reason
                    </div>
                    <p class="gar-adj__reason-text">{{ adj.reason }}</p>
                  </div>
                </div>
              </div>
            </div>

            <!-- Review history -->
            <div v-if="allReviews.length" class="gar-section">
              <div class="gar-section__head">
                <v-icon size="16" color="#6366f1">mdi-history</v-icon>
                <span class="gar-section__title"
                  >Review history · {{ allReviews.length }}</span
                >
              </div>
              <div
                v-for="(rv, i) in allReviews"
                :key="rv.id"
                class="gar-review-card"
                :class="`gar-review-card--${rv.decision}`"
              >
                <div class="gar-review-card__head" @click="toggleReview(i)">
                  <div class="gar-review-card__head-left">
                    <div
                      class="gar-review-card__icon"
                      :class="`gar-review-card__icon--${rv.decision}`"
                    >
                      <v-icon
                        size="14"
                        :color="
                          rv.decision === 'approved' ? '#059669' : '#dc2626'
                        "
                      >
                        {{
                          rv.decision === "approved"
                            ? "mdi-check-circle"
                            : "mdi-close-circle"
                        }}
                      </v-icon>
                    </div>
                    <div>
                      <div class="gar-review-card__role">
                        {{ rv.role === "hod" ? "HOD" : "Supervisor" }}
                        <span
                          class="gar-review-card__decision"
                          :class="`gar-review-card__decision--${rv.decision}`"
                        >
                          {{
                            rv.decision === "approved" ? "Approved" : "Rejected"
                          }}
                        </span>
                      </div>
                      <div class="gar-review-card__date">
                        <v-icon size="11" color="#94a3b8"
                          >mdi-clock-outline</v-icon
                        >
                        {{ formatDate(rv.date) }}
                      </div>
                    </div>
                  </div>
                  <v-icon
                    size="16"
                    color="#94a3b8"
                    :class="{ 'gar-rotate': expandedReviews[i] }"
                    >mdi-chevron-down</v-icon
                  >
                </div>
                <v-expand-transition>
                  <div
                    v-if="expandedReviews[i] && rv.comment"
                    class="gar-review-card__body"
                  >
                    <p class="gar-review-card__text">{{ rv.comment }}</p>
                  </div>
                </v-expand-transition>
              </div>
            </div>
          </v-col>

          <!-- Review panel -->
          <v-col v-if="canReview" cols="5">
            <div class="gar-action-panel">
              <div class="gar-action-panel__accent"></div>
              <div class="gar-action-panel__inner">
                <div class="gar-action-panel__head">
                  <div class="gar-action-panel__icon">
                    <v-icon size="20" color="white">mdi-clipboard-check</v-icon>
                  </div>
                  <div>
                    <div class="gar-action-panel__title">Your Decision</div>
                    <div class="gar-action-panel__sub">
                      Approve or reject the entire adjustment as a bundle.
                    </div>
                  </div>
                </div>
                <v-form ref="reviewForm" v-model="validReview">
                  <div class="gar-field">
                    <label class="gar-field__label"
                      >Comments <span class="red--text">*</span></label
                    >
                    <v-textarea
                      v-model="reviewComment"
                      :rules="[rules.required]"
                      outlined
                      dense
                      hide-details="auto"
                      rows="5"
                      placeholder="Share feedback on the proposed changes…"
                    />
                  </div>
                  <div class="gar-action-panel__actions">
                    <button
                      type="button"
                      class="gar-btn gar-btn--reject"
                      :disabled="!validReview || submitting"
                      @click="confirmDecision('rejected')"
                    >
                      <v-icon left size="14">mdi-close-circle-outline</v-icon>
                      Reject
                    </button>
                    <button
                      type="button"
                      class="gar-btn gar-btn--approve"
                      :disabled="!validReview || submitting"
                      @click="confirmDecision('approved')"
                    >
                      <v-icon left size="14">mdi-check-circle-outline</v-icon>
                      Approve
                    </button>
                  </div>
                </v-form>
              </div>
            </div>
          </v-col>
        </v-row>

        <div v-if="approvedObjectives.length" class="gar-section gar-preview">
          <div class="gar-section__head">
            <v-icon size="16" color="#6366f1">mdi-eye-outline</v-icon>
            <span class="gar-section__title">Approved Plan Preview</span>
          </div>
          <p class="gar-preview__intro">
            This is how the plan will look if the adjustment is approved.
            Replaced and dropped original goals are omitted.
          </p>

          <div class="gar-preview__grid">
            <div
              v-for="(col, ci) in approvedObjectiveColumns"
              :key="`preview-col-${ci}`"
              class="gar-preview__col"
            >
              <div v-for="obj in col" :key="obj.id" class="gar-preview-obj">
                <div
                  class="gar-preview-obj__head"
                  :style="{
                    background: previewGradient(previewObjectiveIndex(obj)),
                  }"
                >
                  <div class="gar-preview-obj__top">
                    <span class="gar-preview-obj__num">
                      {{
                        String(previewObjectiveIndex(obj) + 1).padStart(2, "0")
                      }}
                    </span>
                    <span
                      v-if="previewGoalStatus(obj)"
                      class="gar-preview-pill gar-preview-pill--new"
                    >
                      <v-icon size="10" color="#dcfce7"
                        >mdi-star-four-points</v-icon
                      >
                      {{ previewGoalStatus(obj) }}
                    </span>
                  </div>
                  <div class="gar-preview-obj__title">{{ obj.name }}</div>
                  <div v-if="obj.description" class="gar-preview-obj__desc">
                    {{ obj.description }}
                  </div>
                </div>

                <div class="gar-preview-obj__body">
                  <div
                    v-if="approvedActivities(obj.id).length === 0"
                    class="gar-preview-empty"
                  >
                    <v-icon size="14" color="#94a3b8"
                      >mdi-information-outline</v-icon
                    >
                    No activities in the approved view.
                  </div>

                  <div
                    v-for="(act, ai) in approvedActivities(obj.id)"
                    :key="act.id"
                    class="gar-preview-activity"
                  >
                    <div class="gar-preview-activity__row">
                      <span class="gar-preview-activity__index">
                        {{ previewObjectiveIndex(obj) + 1 }}.{{ ai + 1 }}
                      </span>
                      <div class="gar-preview-activity__content">
                        <div class="gar-preview-activity__head">
                          <div>
                            <div class="gar-preview-activity__name">
                              {{ act.name }}
                            </div>
                            <div
                              v-if="act.description"
                              class="gar-preview-activity__desc"
                            >
                              {{ act.description }}
                            </div>
                          </div>
                          <span
                            v-if="previewGoalStatus(act)"
                            class="gar-preview-pill gar-preview-pill--new gar-preview-pill--sm"
                          >
                            {{ previewGoalStatus(act) }}
                          </span>
                        </div>

                        <div
                          v-if="approvedSubActivities(act.id).length"
                          class="gar-preview-subs"
                        >
                          <div
                            v-for="(sub, si) in approvedSubActivities(act.id)"
                            :key="sub.id"
                            class="gar-preview-sub"
                          >
                            <span class="gar-preview-sub__index">
                              {{ previewObjectiveIndex(obj) + 1 }}.{{
                                ai + 1
                              }}.{{ si + 1 }}
                            </span>
                            <div class="gar-preview-sub__content">
                              <div class="gar-preview-sub__head">
                                <div>
                                  <div class="gar-preview-sub__name">
                                    {{ sub.name }}
                                  </div>
                                  <div
                                    v-if="sub.description"
                                    class="gar-preview-sub__desc"
                                  >
                                    {{ sub.description }}
                                  </div>
                                </div>
                                <span
                                  v-if="previewGoalStatus(sub)"
                                  class="gar-preview-pill gar-preview-pill--new gar-preview-pill--sm"
                                >
                                  {{ previewGoalStatus(sub) }}
                                </span>
                              </div>

                              <div
                                v-if="approvedKpis(sub.id).length"
                                class="gar-preview-kpis"
                              >
                                <div
                                  v-for="kpi in approvedKpis(sub.id)"
                                  :key="kpi.id"
                                  class="gar-preview-kpi"
                                >
                                  <div class="gar-preview-kpi__left">
                                    <v-icon size="12" color="#6366f1"
                                      >mdi-chart-bar</v-icon
                                    >
                                    <div class="gar-preview-kpi__text">
                                      <div class="gar-preview-kpi__head">
                                        <span class="gar-preview-kpi__name">{{
                                          kpi.name
                                        }}</span>
                                        <span
                                          v-if="previewGoalStatus(kpi)"
                                          class="gar-preview-pill gar-preview-pill--new gar-preview-pill--sm"
                                        >
                                          {{ previewGoalStatus(kpi) }}
                                        </span>
                                      </div>
                                      <div
                                        v-if="kpi.description"
                                        class="gar-preview-kpi__desc"
                                      >
                                        {{ kpi.description }}
                                      </div>
                                    </div>
                                  </div>
                                  <div
                                    v-if="approvedTargetForKpi(kpi.id)"
                                    class="gar-preview-target"
                                  >
                                    <v-icon size="11" color="#065f46"
                                      >mdi-bullseye-arrow</v-icon
                                    >
                                    <span>{{
                                      approvedTargetForKpi(kpi.id).name
                                    }}</span>
                                    <span
                                      v-if="
                                        approvedTargetForKpi(kpi.id).description
                                      "
                                      class="gar-preview-target__desc"
                                    >
                                      {{
                                        approvedTargetForKpi(kpi.id).description
                                      }}
                                    </span>
                                  </div>
                                </div>
                              </div>
                            </div>
                          </div>
                        </div>

                        <div
                          v-if="approvedKpis(act.id).length"
                          class="gar-preview-kpis"
                        >
                          <div
                            v-for="kpi in approvedKpis(act.id)"
                            :key="kpi.id"
                            class="gar-preview-kpi"
                          >
                            <div class="gar-preview-kpi__left">
                              <v-icon size="12" color="#6366f1"
                                >mdi-chart-bar</v-icon
                              >
                              <div class="gar-preview-kpi__text">
                                <div class="gar-preview-kpi__head">
                                  <span class="gar-preview-kpi__name">{{
                                    kpi.name
                                  }}</span>
                                  <span
                                    v-if="previewGoalStatus(kpi)"
                                    class="gar-preview-pill gar-preview-pill--new gar-preview-pill--sm"
                                  >
                                    {{ previewGoalStatus(kpi) }}
                                  </span>
                                </div>
                                <div
                                  v-if="kpi.description"
                                  class="gar-preview-kpi__desc"
                                >
                                  {{ kpi.description }}
                                </div>
                              </div>
                            </div>
                            <div
                              v-if="approvedTargetForKpi(kpi.id)"
                              class="gar-preview-target"
                            >
                              <v-icon size="11" color="#065f46"
                                >mdi-bullseye-arrow</v-icon
                              >
                              <span>{{
                                approvedTargetForKpi(kpi.id).name
                              }}</span>
                              <span
                                v-if="approvedTargetForKpi(kpi.id).description"
                                class="gar-preview-target__desc"
                              >
                                {{ approvedTargetForKpi(kpi.id).description }}
                              </span>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                <div class="gar-preview-obj__foot">
                  <span
                    >{{ approvedActivities(obj.id).length }} activities</span
                  >
                  <span>{{ countApprovedKpisForObjective(obj.id) }} KPIs</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </template>
    </div>

    <!-- Confirm dialog -->
    <v-dialog v-model="confirmDialog" max-width="460" persistent>
      <v-card class="gar-dialog">
        <div
          class="gar-dialog__strip"
          :class="
            pendingDecision === 'approved'
              ? 'gar-dialog__strip--approve'
              : 'gar-dialog__strip--reject'
          "
        ></div>
        <div class="gar-dialog__head">
          <div
            class="gar-dialog__head-icon"
            :class="
              pendingDecision === 'approved'
                ? 'gar-dialog__head-icon--approve'
                : 'gar-dialog__head-icon--reject'
            "
          >
            <v-icon color="white">{{
              pendingDecision === "approved"
                ? "mdi-check-circle"
                : "mdi-close-circle"
            }}</v-icon>
          </div>
          <div>
            <div class="gar-dialog__title">
              {{
                pendingDecision === "approved"
                  ? "Approve adjustment?"
                  : "Reject adjustment?"
              }}
            </div>
            <div class="gar-dialog__sub">
              {{
                pendingDecision === "approved"
                  ? currentReviewer === "hod"
                    ? "HOD approval applies the changes to the plan. Semester 2 review will use the new goals."
                    : "Supervisor approval forwards the adjustment to the HOD for final review."
                  : "Rejection returns the adjustment to the staff for revision."
              }}
            </div>
          </div>
        </div>
        <div class="gar-dialog__body">
          <div class="gar-dialog__preview">
            <div class="gar-dialog__preview-label">Your comment</div>
            <p class="gar-dialog__preview-text">
              {{ reviewComment || "—" }}
            </p>
          </div>
        </div>
        <div class="gar-dialog__foot">
          <button class="gar-btn gar-btn--ghost" @click="confirmDialog = false">
            Cancel
          </button>
          <button
            class="gar-btn"
            :class="
              pendingDecision === 'approved'
                ? 'gar-btn--approve'
                : 'gar-btn--reject'
            "
            :disabled="submitting"
            @click="submitDecision"
          >
            <v-icon left size="14">
              {{
                pendingDecision === "approved"
                  ? "mdi-check-circle-outline"
                  : "mdi-close-circle-outline"
              }}
            </v-icon>
            Confirm
            {{ pendingDecision === "approved" ? "Approval" : "Rejection" }}
          </button>
        </div>
      </v-card>
    </v-dialog>

    <v-snackbar
      v-model="snackbar"
      :color="snackbarColor"
      :timeout="3500"
      top
      right
    >
      <v-icon left>{{ snackbarIcon }}</v-icon>
      {{ snackbarMessage }}
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";
import processQuestionnaire from "../../mixins/processQuestionnaire";

/**
 * Unified goal-adjustment review component.
 * The active reviewer stage is derived from the performance plan
 * goal-adjustment status rather than a route role parameter.
 */
export default {
  name: "GoalAdjustmentReview",
  mixins: [generalMixin, processQuestionnaire],

  data() {
    return {
      fhir: {},

      loading: false,
      submitting: false,

      accessChecked: false,
      isHOD: false,
      allowedFacilities: [],

      selectedFiscalYear: "",
      staffName: "",

      performancePlan: null,
      objectives: [],
      activities: [],
      subActivities: [],
      kpis: [],
      targets: [],

      adjustments: [],
      supervisorReviews: [],
      hodReviews: [],
      expandedReviews: {},

      reviewComment: "",
      validReview: true,
      confirmDialog: false,
      pendingDecision: null,

      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      snackbarIcon: "mdi-check-circle",

      rules: {
        required: (v) => (!!v && String(v).trim() !== "") || "Required",
      },
    };
  },

  computed: {
    queries() {
      return this.$route?.query || {};
    },
    adjustmentStatus() {
      return this.performancePlan?.adjustmentStatus || "none";
    },
    currentReviewer() {
      if (this.adjustmentStatus === "submitted") return "supervisor";
      if (this.adjustmentStatus === "supervisor-approved") return "hod";
      if (
        this.adjustmentStatus === "supervisor-rejected" ||
        this.adjustmentStatus === "hod-rejected"
      ) {
        return "staff";
      }
      if (
        this.adjustmentStatus === "hod-approved" ||
        this.adjustmentStatus === "applied"
      ) {
        return "done";
      }
      return "staff";
    },
    profile() {
      if (this.currentReviewer === "hod") {
        return "http://ihris.org/fhir/StructureDefinition/hod-goal-adjustment-review-profile";
      }
      return "http://ihris.org/fhir/StructureDefinition/supervisor-goal-adjustment-review-profile";
    },
    url() {
      if (this.currentReviewer === "hod") {
        return "http://ihris.org/fhir/Questionnaire/hod-goal-adjustment-review";
      }
      return "http://ihris.org/fhir/Questionnaire/supervisor-goal-adjustment-review";
    },
    currentReviewerLabel() {
      const map = {
        supervisor: "Supervisor Review",
        hod: "HOD Review",
        staff: "Staff Action",
        done: "Review Complete",
      };
      return map[this.currentReviewer] || "Adjustment Review";
    },
    adjustmentStatusLabel() {
      const map = {
        none: "No Adjustment",
        draft: "Draft",
        submitted: "Submitted",
        "supervisor-approved": "Supervisor Approved",
        "supervisor-rejected": "Supervisor Rejected",
        "hod-approved": "HOD Approved",
        "hod-rejected": "HOD Rejected",
        applied: "Applied",
      };
      return map[this.adjustmentStatus] || this.adjustmentStatus;
    },
    isSupervisor() {
      return (
        !!this.loggedInStaff.practitioner &&
        this.practitionerProfile?.supervisor?.practitioner ===
          this.loggedInStaff.practitioner
      );
    },
    staffInCoverage() {
      return this.allowedFacilities.some(
        (f) => String(f.id) === String(this.practitionerProfile?.facility),
      );
    },
    hodCanAccess() {
      return [
        "supervisor-approved",
        "hod-approved",
        "hod-rejected",
        "applied",
      ].includes(this.adjustmentStatus);
    },
    canReview() {
      if (this.adjustmentStatus === "submitted" && this.isSupervisor)
        return true;
      if (
        this.adjustmentStatus === "supervisor-approved" &&
        this.isHOD &&
        this.staffInCoverage
      )
        return true;
      return false;
    },
    statusBanner() {
      if (this.adjustmentStatus === "draft")
        return {
          type: "info",
          icon: "mdi-clock-outline",
          title: "Awaiting submission.",
          text:
            "The staff member has not yet submitted this adjustment for review.",
        };
      if (this.adjustmentStatus === "supervisor-rejected")
        return {
          type: "warning",
          icon: "mdi-alert-circle-outline",
          title: "Returned to staff.",
          text:
            "Supervisor rejected this adjustment. Staff must revise and resubmit.",
        };
      if (this.adjustmentStatus === "hod-rejected")
        return {
          type: "warning",
          icon: "mdi-alert-circle-outline",
          title: "Returned to staff.",
          text: "HOD rejected this adjustment. Staff must revise and resubmit.",
        };
      if (this.adjustmentStatus === "hod-approved")
        return {
          type: "success",
          icon: "mdi-check-circle-outline",
          title: "Approved.",
          text:
            "HOD approved this adjustment and adjustments applied successfuly",
        };
      return null;
    },
    dropsCount() {
      return this.adjustments.filter((a) => a.adjustmentType === "drop").length;
    },
    modifiesCount() {
      return this.adjustments.filter((a) =>
        ["replace", "modify"].includes(a.adjustmentType),
      ).length;
    },
    addsCount() {
      return this.adjustments.filter((a) => a.adjustmentType === "add").length;
    },
    approvedObjectives() {
      return this.buildApprovedGoalList(this.objectives, null);
    },
    approvedObjectiveColumns() {
      const cols = [[], []];
      this.approvedObjectives.forEach((obj, i) => {
        cols[i % 2].push(obj);
      });
      return cols;
    },
    allReviews() {
      const joined = [
        ...this.supervisorReviews.map((r) => ({ ...r, role: "supervisor" })),
        ...this.hodReviews.map((r) => ({ ...r, role: "hod" })),
      ];
      return joined.sort((a, b) => new Date(b.date) - new Date(a.date));
    },
  },

  async mounted() {
    let fy = await fetch("/site/leave/getFinancialYear");
    fy = await fy.json();
    this.selectedFiscalYear = fy.year;

    await this.initialize();
  },

  watch: {
    loadingUserData: {
      immediate: true,
      async handler(isLoading) {
        if (isLoading === false) {
          await this.checkAccess();
        }
      },
    },
  },

  methods: {
    _ext(r, url) {
      return r.extension?.find((e) => e.url.includes(url));
    },

    async checkAccess() {
      try {
        if (!this.loggedInStaff.practitioner) {
          this.accessChecked = true;
          return;
        }
        const resp = await fetch(
          `/site/general/getHOD/${this.loggedInStaff.practitioner}`,
        );
        if (!resp.ok) throw new Error("HTTP " + resp.status);
        const hodList = await resp.json();
        const practitionerId = this.loggedInStaff.practitioner;
        const matched = Array.isArray(hodList)
          ? hodList.find((h) => h.practitioners.includes(practitionerId))
          : null;
        this.isHOD = !!matched;
        const coverageArr = Array.isArray(matched?.coverage)
          ? matched.coverage
          : [];
        this.allowedFacilities = coverageArr.map((f) => ({
          id: f.id,
          name: f.name,
        }));
      } catch (err) {
        console.error("checkAccess error:", err);
        this.isHOD = false;
      } finally {
        this.accessChecked = true;
      }
    },

    async initialize() {
      this.loading = true;
      try {
        await this.loadStaffName();
        await this.loadPlan();
        this.syncReviewContext();
        if (this.performancePlan) {
          await Promise.all([
            this.loadObjectives(),
            this.loadSupervisorReviews(),
            this.loadHodReviews(),
          ]);
          await this.loadActivities();
          await this.loadSubActivities();
          await this.loadKpis();
          await this.loadTargets();
          await this.loadAdjustments();
        }
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error loading adjustment", "error");
      } finally {
        this.loading = false;
      }
    },
    syncReviewContext() {
      if (this.currentReviewer === "hod") {
        this.url =
          "http://ihris.org/fhir/Questionnaire/hod-goal-adjustment-review";
        this.profile =
          "http://ihris.org/fhir/StructureDefinition/hod-goal-adjustment-review-profile";
        return;
      }
      if (this.currentReviewer === "supervisor") {
        this.url =
          "http://ihris.org/fhir/Questionnaire/supervisor-goal-adjustment-review";
        this.profile =
          "http://ihris.org/fhir/StructureDefinition/supervisor-goal-adjustment-review-profile";
        return;
      }
      this.url = "";
      this.profile = "";
    },

    async loadStaffName() {
      if (!this.queries.practitioner) return;
      try {
        const r = await fetch(
          `/fhir/Practitioner/${this.queries.practitioner}`,
        );
        const p = await r.json();
        if (p?.name?.[0]) {
          const n = p.name[0];
          const parts = [n.given?.join(" ") || "", n.family || ""].filter(
            Boolean,
          );
          this.staffName = parts.join(" ");
        }
      } catch (e) {
        console.error("staff name", e);
      }
    },

    async loadPlan() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-plan-profile",
        practitioner: `Practitioner/${this.queries.practitioner}`,
        fiscalyear: this.selectedFiscalYear,
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      if (b.entry?.length) {
        const res = b.entry[0].resource;
        this.performancePlan = {
          id: res.id,
          name: this._ext(res, "ihris-basic-name")?.valueString || "",
          adjustmentStatus:
            this._ext(res, "goal-adjustment-status")?.valueCoding?.code ||
            "none",
        };
      }
    },

    async loadObjectives() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-objective-profile",
        performanceplan: `Basic/${this.performancePlan.id}`,
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.objectives = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "objective"))
        : [];
    },
    async loadActivities() {
      if (!this.objectives.length) return (this.activities = []);
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-activity-profile",
        parent: this.objectives.map((o) => o.id).join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.activities = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "activity"))
        : [];
    },
    async loadSubActivities() {
      if (!this.activities.length) return (this.subActivities = []);
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-subactivity-profile",
        parent: this.activities.map((a) => a.id).join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.subActivities = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "subactivity"))
        : [];
    },
    async loadKpis() {
      const parents = [
        ...this.activities.map((a) => a.id),
        ...this.subActivities.map((s) => s.id),
      ];
      if (!parents.length) return (this.kpis = []);
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-kpi-profile",
        parent: parents.join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.kpis = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "kpi"))
        : [];
    },
    async loadTargets() {
      if (!this.kpis.length) return (this.targets = []);
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/performance-target-profile",
        parent: this.kpis.map((k) => k.id).join(","),
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.targets = b.entry
        ? b.entry.map((e) => this._extractGoal(e.resource, "target"))
        : [];
    },
    _extractGoal(r, goalType) {
      return {
        id: r.id,
        goalType,
        name: this._ext(r, "ihris-basic-name")?.valueString || "",
        description: this._ext(r, "description")?.valueString || "",
        parentId:
          this._ext(r, "parent")?.valueReference?.reference?.split("/")[1] ||
          null,
        lifecycleStatus:
          this._ext(r, "goal-lifecycle-status")?.valueCoding?.code ||
          "original-active",
      };
    },

    async loadAdjustments() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/goal-adjustment-profile",
        practitioner: `Practitioner/${this.queries.practitioner}`,
        _sort: "-_lastUpdated",
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      const raw =
        b.entry?.map((e) => this._extractAdjustment(e.resource)) || [];
      const planGoalIds = new Set([
        ...this.objectives.map((o) => o.id),
        ...this.activities.map((a) => a.id),
        ...this.subActivities.map((s) => s.id),
        ...this.kpis.map((k) => k.id),
        ...this.targets.map((t) => t.id),
      ]);
      this.adjustments = raw.filter(
        (a) =>
          (a.oldGoalId && planGoalIds.has(a.oldGoalId)) ||
          (a.supersededById && planGoalIds.has(a.supersededById)),
      );
    },
    _extractAdjustment(r) {
      return {
        id: r.id,
        adjustmentType:
          this._ext(r, "goal-adjustment-type")?.valueCoding?.code || "",
        oldGoalId:
          this._ext(r, "old-goal")?.valueReference?.reference?.split("/")[1] ||
          null,
        supersededById:
          this._ext(r, "superseded-by-goal")?.valueReference?.reference?.split(
            "/",
          )[1] || null,
        reason: this._ext(r, "reason")?.valueString || "",
        eventDate: this._ext(r, "event-date")?.valueDate || "",
      };
    },

    async loadSupervisorReviews() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/supervisor-goal-adjustment-review-profile",
        performanceplan: `Basic/${this.performancePlan.id}`,
        _sort: "-_lastUpdated",
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.supervisorReviews = b.entry
        ? b.entry.map((e) => this._extractReview(e.resource))
        : [];
    },
    async loadHodReviews() {
      const params = new URLSearchParams({
        _profile:
          "http://ihris.org/fhir/StructureDefinition/hod-goal-adjustment-review-profile",
        performanceplan: `Basic/${this.performancePlan.id}`,
        _sort: "-_lastUpdated",
      });
      const r = await fetch(`/fhir/Basic?${params}`);
      const b = await r.json();
      this.hodReviews = b.entry
        ? b.entry.map((e) => this._extractReview(e.resource))
        : [];
    },
    _extractReview(r) {
      return {
        id: r.id,
        comment: this._ext(r, "description")?.valueString || "",
        decision: this._ext(r, "review-status")?.valueCoding?.code || "",
        date: r.meta?.lastUpdated,
      };
    },

    // ─── Lookups ─────────────────────────────────────────────────────────
    _findGoal(id) {
      if (!id) return null;
      return (
        this.objectives.find((g) => g.id === id) ||
        this.activities.find((g) => g.id === id) ||
        this.subActivities.find((g) => g.id === id) ||
        this.kpis.find((g) => g.id === id) ||
        this.targets.find((g) => g.id === id) ||
        null
      );
    },
    goalName(id) {
      return this._findGoal(id)?.name || "(unknown)";
    },
    goalDesc(id) {
      return this._findGoal(id)?.description || "";
    },
    adjGoalType(adj) {
      const g = this._findGoal(adj.supersededById || adj.oldGoalId);
      return g ? g.goalType : "";
    },
    goalParentName(id) {
      const g = this._findGoal(id);
      if (!g || !g.parentId) return "";
      return this._findGoal(g.parentId)?.name || "";
    },
    // Build breadcrumb path up to objective
    goalPath(id) {
      const g = this._findGoal(id);
      if (!g) return "";
      const chain = [];
      let cur = g;
      let guard = 10;
      while (cur && guard-- > 0) {
        chain.unshift(cur.name);
        if (cur.goalType === "objective") break;
        cur = this._findGoal(cur.parentId);
      }
      return chain.join(" › ");
    },
    replaceAdjForGoal(goal) {
      if (!goal) return null;
      const adj = this.adjustments.find(
        (a) =>
          ["replace", "modify"].includes(a.adjustmentType) &&
          a.oldGoalId === goal.id,
      );
      if (!adj) return null;
      return {
        adj,
        newGoal: adj.supersededById ? this._findGoal(adj.supersededById) : null,
      };
    },
    replaceSourceAdj(goal) {
      if (!goal) return null;
      return (
        this.adjustments.find(
          (a) =>
            ["replace", "modify"].includes(a.adjustmentType) &&
            a.supersededById === goal.id,
        ) || null
      );
    },
    dropAdjForGoal(goal) {
      if (!goal) return null;
      return (
        this.adjustments.find(
          (a) => a.adjustmentType === "drop" && a.oldGoalId === goal.id,
        ) || null
      );
    },
    isApprovedDropped(goal) {
      // After HOD approval, replaced and dropped originals are both marked
      // original-dropped, so lifecycle alone is not enough to decide whether
      // the goal should disappear from the approved preview.
      return !!goal && !!this.dropAdjForGoal(goal);
    },
    effectiveParentId(goal) {
      if (!goal || !goal.parentId) return null;
      const parent = this._findGoal(goal.parentId);
      const replacement = this.replaceAdjForGoal(parent);
      return replacement?.adj?.supersededById || goal.parentId;
    },
    belongsToApprovedParent(goal, parentId) {
      if (!goal) return false;
      return parentId
        ? this.effectiveParentId(goal) === parentId
        : !goal.parentId;
    },
    hasDroppedAncestor(goal) {
      let currentId = goal?.parentId;
      let guard = 10;
      while (currentId && guard-- > 0) {
        const parent = this._findGoal(currentId);
        if (!parent) break;
        if (this.isApprovedDropped(parent)) return true;
        currentId = parent.parentId;
      }
      return false;
    },
    buildApprovedGoalList(goals, parentId = null) {
      const siblings = goals.filter((goal) =>
        this.belongsToApprovedParent(goal, parentId),
      );
      const result = [];
      const seen = new Set();

      for (const goal of siblings) {
        if (seen.has(goal.id)) continue;
        if (this.isApprovedDropped(goal) || this.hasDroppedAncestor(goal)) {
          seen.add(goal.id);
          continue;
        }

        const replacement = this.replaceAdjForGoal(goal);
        if (replacement) {
          const newGoal =
            replacement.newGoal ||
            this._findGoal(replacement.adj.supersededById);
          if (
            newGoal &&
            !seen.has(newGoal.id) &&
            !this.isApprovedDropped(newGoal) &&
            !this.hasDroppedAncestor(newGoal) &&
            this.belongsToApprovedParent(newGoal, parentId)
          ) {
            result.push(newGoal);
            seen.add(newGoal.id);
          }
          seen.add(goal.id);
          continue;
        }

        const replaceSource = this.replaceSourceAdj(goal);
        if (replaceSource) {
          const oldGoal = this._findGoal(replaceSource.oldGoalId);
          if (oldGoal && this.belongsToApprovedParent(oldGoal, parentId)) {
            seen.add(goal.id);
            continue;
          }
        }

        result.push(goal);
        seen.add(goal.id);
      }

      return result;
    },
    approvedActivities(objectiveId) {
      return this.buildApprovedGoalList(this.activities, objectiveId);
    },
    approvedSubActivities(activityId) {
      return this.buildApprovedGoalList(this.subActivities, activityId);
    },
    approvedKpis(parentId) {
      return this.buildApprovedGoalList(this.kpis, parentId);
    },
    approvedTargetForKpi(kpiId) {
      return this.buildApprovedGoalList(this.targets, kpiId)[0] || null;
    },
    previewGoalStatus(goal) {
      if (!goal) return "";
      return goal.lifecycleStatus === "added-at-midyear" ? "New" : "";
    },
    previewObjectiveIndex(obj) {
      return this.approvedObjectives.findIndex((goal) => goal.id === obj.id);
    },
    countApprovedKpisForObjective(objectiveId) {
      let count = 0;
      for (const activity of this.approvedActivities(objectiveId)) {
        count += this.approvedKpis(activity.id).length;
        for (const subActivity of this.approvedSubActivities(activity.id)) {
          count += this.approvedKpis(subActivity.id).length;
        }
      }
      return count;
    },

    // ─── Display helpers ─────────────────────────────────────────────────
    chipIcon(t) {
      return t === "drop"
        ? "mdi-delete-outline"
        : ["replace", "modify"].includes(t)
        ? "mdi-swap-horizontal"
        : "mdi-plus-circle-outline";
    },
    chipColor(t) {
      return t === "drop"
        ? "#dc2626"
        : ["replace", "modify"].includes(t)
        ? "#d97706"
        : "#059669";
    },
    chipLabel(t) {
      return t === "drop"
        ? "Drop"
        : ["replace", "modify"].includes(t)
        ? "Replace"
        : "Add";
    },
    goalTypeLabel(t) {
      const m = {
        objective: "Objective",
        activity: "Activity",
        subactivity: "Sub-Activity",
        kpi: "KPI",
        target: "Target",
      };
      return m[t] || "Goal";
    },
    toggleReview(i) {
      this.$set(this.expandedReviews, i, !this.expandedReviews[i]);
    },
    formatDate(d) {
      if (!d) return "";
      try {
        return new Intl.DateTimeFormat("en-GB", {
          day: "2-digit",
          month: "short",
          year: "numeric",
          hour: "2-digit",
          minute: "2-digit",
        }).format(new Date(d));
      } catch {
        return d;
      }
    },
    previewGradient(i) {
      const gradients = [
        "linear-gradient(135deg, #0c1f3f 0%, #1a3a6e 100%)",
        "linear-gradient(135deg, #1f3b2f 0%, #0f766e 100%)",
        "linear-gradient(135deg, #4c1d95 0%, #7c3aed 100%)",
        "linear-gradient(135deg, #7c2d12 0%, #ea580c 100%)",
      ];
      return gradients[i % gradients.length];
    },

    // ─── Decision ────────────────────────────────────────────────────────
    confirmDecision(decision) {
      if (!this.$refs.reviewForm.validate()) return;
      this.pendingDecision = decision;
      this.confirmDialog = true;
    },
    async submitDecision() {
      this.submitting = true;
      try {
        this.syncReviewContext();
        this.fhir = {
          type:
            this.currentReviewer === "hod"
              ? "hod-adjustment-review"
              : "supervisor-adjustment-review",
          performancePlanId: this.performancePlan.id,
          decision: this.pendingDecision,
          comment: this.reviewComment.trim(),
        };
        await this.processFHIR();
        this.confirmDialog = false;
        this.reviewComment = "";
        this.showSnackbar(
          `Adjustment ${
            this.pendingDecision === "approved" ? "approved" : "rejected"
          }`,
          "success",
        );
        await this.initialize();
      } catch (e) {
        console.error(e);
        this.showSnackbar("Error submitting decision", "error");
      } finally {
        this.submitting = false;
      }
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbarIcon =
        color === "success"
          ? "mdi-check-circle"
          : color === "error"
          ? "mdi-alert-circle"
          : "mdi-information";
      this.snackbar = true;
    },
  },
};
